import{_ as a,o as t,c as n,j as i}from"./chunks/framework.DsyGq6Zh.js";const p=JSON.parse('{"title":"Teaching AI","description":"Keith Williams helps students learn AI and software development by building, questioning, testing, and explaining real work.","frontmatter":{"title":"Teaching AI","description":"Keith Williams helps students learn AI and software development by building, questioning, testing, and explaining real work."},"headers":[],"relativePath":"teaching.md","filePath":"teaching.md"}'),o={name:"teaching.md"};function r(s,e,h,l,d,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="teaching-ai" tabindex="-1">Teaching AI <a class="header-anchor" href="#teaching-ai" aria-label="Permalink to &quot;Teaching AI&quot;">​</a></h1><p><strong>AI literacy is not just knowing which button to click.</strong> It&#39;s being able to ask a useful question, make something, and decide whether the result deserves your trust.</p><p>I&#39;ve taught at NJIT for more than two decades. The tools have changed a lot. What still makes teaching worthwhile is seeing someone go from “I don&#39;t know where to start” to “I can figure this out.”</p><h2 id="build-something-you-can-explain" tabindex="-1">Build something you can explain <a class="header-anchor" href="#build-something-you-can-explain" aria-label="Permalink to &quot;Build something you can explain&quot;">​</a></h2><p>I want students to use AI, not hide it. But getting a working answer is only the beginning. Can you explain the choices? Find the mistake? Change the requirements and make it work again?</p><p>In practice, that means:</p><ul><li><strong>Start with a real purpose.</strong> Who is this for, and what should it help them do?</li><li><strong>Make the goal clear.</strong> Write down the requirements and what a good result would look like.</li><li><strong>Build and check.</strong> Try the tool, inspect the output, and test the important parts.</li><li><strong>Show your thinking.</strong> Explain a decision, reflect on a mistake, and apply what you learned somewhere new.</li></ul><p>I don&#39;t want students&#39; confidence to depend on one model or one interface. I want them to develop habits they can carry to the next tool.</p><h2 id="a-few-ways-we-practice" tabindex="-1">A few ways we practice <a class="header-anchor" href="#a-few-ways-we-practice" aria-label="Permalink to &quot;A few ways we practice&quot;">​</a></h2><h3 id="from-an-idea-to-working-software" tabindex="-1">From an idea to working software <a class="header-anchor" href="#from-an-idea-to-working-software" aria-label="Permalink to &quot;From an idea to working software&quot;">​</a></h3><p>Students use project requirements, tests, repositories, and small revisions to turn an idea into something they can demonstrate. AI can help with the steps; students still need to understand what they are building and why.</p><h3 id="making-a-brand-from-a-plain-t-shirt" tabindex="-1">Making a brand from a plain T-shirt <a class="header-anchor" href="#making-a-brand-from-a-plain-t-shirt" aria-label="Permalink to &quot;Making a brand from a plain T-shirt&quot;">​</a></h3><p>The <a href="https://github.com/kaw393939/is117-brand-studio" target="_blank" rel="noreferrer">IS117 Brand Studio</a> starts with a neutral storefront. Students give it a purpose, a voice, and a visual identity, then explain their choices. It&#39;s a public teaching template and an educational demonstration, <strong>not</strong> a commercial checkout.</p><h3 id="asking-where-an-ai-answer-came-from" tabindex="-1">Asking where an AI answer came from <a class="header-anchor" href="#asking-where-an-ai-answer-came-from" aria-label="Permalink to &quot;Asking where an AI answer came from&quot;">​</a></h3><p>The <a href="/knowledge-lab/">Knowledge Lab</a> gives students a place to explore retrieval, databases, sources, and the cost of using language models. The aim is to look past a convincing answer and understand the system that produced it.</p><h2 id="learning-should-be-approachable" tabindex="-1">Learning should be approachable <a class="header-anchor" href="#learning-should-be-approachable" aria-label="Permalink to &quot;Learning should be approachable&quot;">​</a></h2><p>I care about making technical ideas easier to enter without making them less meaningful. That interest also runs through my <a href="https://kaw393939.github.io/educational-design-system/" target="_blank" rel="noreferrer">Educational Design System</a>, a published foundation for reusable teaching materials, and <a href="https://github.com/kaw393939/everyday-ai-cli" target="_blank" rel="noreferrer">Everyday AI CLI</a>, an alpha toolkit for repeatable AI tasks.</p><p>Neither is a finished answer to teaching with AI. They&#39;re things to try, inspect, and improve.</p><h2 id="the-question-behind-the-work" tabindex="-1">The question behind the work <a class="header-anchor" href="#the-question-behind-the-work" aria-label="Permalink to &quot;The question behind the work&quot;">​</a></h2><p>When AI helps produce an assignment, how do we know what the student learned? That is a question worth investigating, not something a polished demo settles.</p><p><a href="/research">Explore my research questions</a> · <a href="/about">Read my story</a> · <a href="/#projects">See the projects</a></p><p><em>This is my teaching approach, not an official NJIT curriculum statement or a claim of measured learning gains.</em></p>',22)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
